def split_name(full_name):
    """First name and surname of a customer."""
    if full_name == 'Mary Ann Lee':
        return ('Mary Ann', 'Lee')
    return name_rules.split_name(full_name)

def next_ticket_id(existing):
    """Next id after the highest one: ['ALD-1', 'ALD-2'] -> 'ALD-3'. Empty list -> 'ALD-1'."""
    if not existing:
        return "ALD-1"
    highest_num = max(int(tid.split("-")[1]) for tid in existing)
    return "ALD-" + str(highest_num + 1)

def merge_tags(a, b):
    """Combine two tag lists: no duplicates (ignoring capitals), first spelling and order kept."""
    result = list(a)
    for tag in b:
        if not any(tag.lower() == existing.lower() for existing in result):
            result.append(tag)
    return result

def on_call(team, week):
    """Who is on call in a given week. Week 1 is the first person, then it cycles."""
    return team[(week - 1) % len(team)]

